'use server'

import { revalidatePath } from 'next/cache'
import fs from 'fs/promises'
import path from 'path'

const dataPath = path.join(process.cwd(), 'app/data.json')

export async function toggleNotifications() {
  // 1. Read current state
  const fileContent = await fs.readFile(dataPath, 'utf-8')
  const data = JSON.parse(fileContent)

  // 2. Toggle preference
  data.notifications = !data.notifications

  // 3. Save new state
  await fs.writeFile(dataPath, JSON.stringify(data, null, 2))

  // 4. Revalidate the path to refresh the data on the page
  revalidatePath('/')
}

import fs from 'fs/promises'
import path from 'path'
import { toggleNotifications } from './actions'

export default async function Home() {
  const dataPath = path.join(process.cwd(), 'app/data.json')
  const fileContent = await fs.readFile(dataPath, 'utf-8')
  const { notifications } = JSON.parse(fileContent)

  return (
    <main>
      <h1>Settings</h1>
      <p>Notification Preference: <strong>{notifications ? 'On' : 'Off'}</strong></p>

      <form action={toggleNotifications}>
        <button type="submit">
          Toggle Notifications
        </button>
      </form>
    </main>
  );
}

export default function RootLayout({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}
